273	    return f'<details class="{classe}"><summary>{escape(resumo)}</summary><div class="dentro">{conteudo}</div></details>'
274	
275	
276	def tabela(
277	    cabecalho: Sequence[str],
278	    linhas: Iterable[Sequence[str]],
279	    identificador: str = "",
280	    numericas: Iterable[int] = (),
281	    compacta: bool = False,
282	    vazia_com: str = "Lista vazia.",
283	) -> str:
284	    """As células de `linhas` já vêm escapadas; o cabeçalho é texto."""
285	    alinhadas = set(numericas)
286	    corpo = "".join(
287	        "<tr>" + "".join(_celula("td", celula, posicao in alinhadas) for posicao, celula in enumerate(linha)) + "</tr>"
288	        for linha in linhas
289	    )
290	    if not corpo:
291	        return vazia(vazia_com)
292	    atributos = (f' id="{identificador}"' if identificador else "") + (' class="compacta"' if compacta else "")
293	    colunas = "".join(_celula("th", escape(coluna), posicao in alinhadas) for posicao, coluna in enumerate(cabecalho))
294	    return (
295	        f'<div class="cartao tabela"><table{atributos}><thead><tr>{colunas}</tr></thead>'
296	        f"<tbody>{corpo}</tbody></table></div>"
297	    )
298	
299	
300	def _celula(tag: str, conteudo: str, numerica: bool) -> str:
301	    return f'<{tag} class="num">{conteudo}</{tag}>' if numerica else f"<{tag}>{conteudo}</{tag}>"
302	
303	
304	def campo_oculto(nome: str, valor: str) -> str:
305	    return f'<input type="hidden" name="{nome}" value="{escape(valor)}">'
306	
307	
308	def renderizar_recusa(mensagem: str, titulo: str = "Decisão não registrada") -> str:
309	    return documento(
310	        titulo,
311	        cabecalho_da_pagina(titulo)
312	        + f'<div class="aviso problema"><p id="recusa">{escape(mensagem)}</p></div>'
313	        + '<p><a href="/">Voltar à conciliação</a></p>',
314	    )
315	
316	
317	_LARGURA_DO_ROTULO = 280
318	_LARGURA_DAS_BARRAS = 320
319	_LARGURA_DO_VALOR = 200
320	_ALTURA_DA_LINHA = 30
321	_ALTURA_DA_BARRA = 16
322	_RAIO = 4
323	
324	
325	def grafico_de_barras(
326	    identificador: str,
327	    grupos: Sequence[GrupoDaCausaRaiz],
328	    medida: Callable[[GrupoDaCausaRaiz], int],
329	    rotulo_da_medida: Callable[[GrupoDaCausaRaiz], str],
330	) -> str:
331	    maior = max((medida(grupo) for grupo in grupos), default=0)
332	    largura = _LARGURA_DO_ROTULO + _LARGURA_DAS_BARRAS + _LARGURA_DO_VALOR
333	    altura = _ALTURA_DA_LINHA * len(grupos)
334	    barras = []
335	    for posicao, grupo in enumerate(grupos):
336	        topo = posicao * _ALTURA_DA_LINHA
337	        base_do_texto = topo + _ALTURA_DA_LINHA // 2 + 4
338	        comprimento = _LARGURA_DAS_BARRAS * medida(grupo) / maior if maior else 0.0
339	        rotulo = escape(rotulo_da_medida(grupo))
340	        barras.append(
341	            f'<g class="barra"><title>{escape(grupo.nome)}: {rotulo}</title>'
342	            f'<text x="0" y="{base_do_texto}">{escape(grupo.nome)}</text>'
343	            + _barra(_LARGURA_DO_ROTULO, topo + (_ALTURA_DA_LINHA - _ALTURA_DA_BARRA) / 2, comprimento)
344	            + f'<text class="valor" x="{_LARGURA_DO_ROTULO + comprimento + 8:.1f}" y="{base_do_texto}">{rotulo}</text>'
345	            "</g>"
346	        )
347	    base = f'<line class="base" x1="{_LARGURA_DO_ROTULO}" y1="0" x2="{_LARGURA_DO_ROTULO}" y2="{altura}"></line>'
348	    return (
349	        f'<div class="grafico"><svg id="{identificador}" role="img" width="{largura}" height="{altura}" '
350	        f'viewBox="0 0 {largura} {altura}">{"".join(barras)}{base}</svg></div>'
351	    )
352	
353	
354	def _barra(x: float, y: float, comprimento: float) -> str:
355	    """Barra horizontal com a ponta arredondada e a base reta, encostada no eixo."""
356	    raio = min(_RAIO, comprimento)
357	    fim = x + comprimento
358	    caminho = (
359	        f"M{x:.1f},{y:.1f} H{fim - raio:.1f} Q{fim:.1f},{y:.1f} {fim:.1f},{y + raio:.1f} "
360	        f"V{y + _ALTURA_DA_BARRA - raio:.1f} Q{fim:.1f},{y + _ALTURA_DA_BARRA:.1f} {fim - raio:.1f},"
361	        f"{y + _ALTURA_DA_BARRA:.1f} H{x:.1f} Z"
362	    )
363	    return f'<path class="marca-da-barra" d="{caminho}" data-comprimento="{comprimento:.1f}"></path>'
364

